<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\AuditLog; use App\Models\CollectionFollowup; use App\Models\Invoice; use Illuminate\Http\Request;
class ManagementController extends Controller {
 public function audit(Request $r){$q=AuditLog::where('company_id',$r->user()->company_id)->with('user')->latest();if($r->filled('action'))$q->where('action',$r->action);return $q->paginate($r->integer('per_page',30));}
 public function followups(Request $r){$q=CollectionFollowup::where('company_id',$r->user()->company_id)->with(['client','invoice','user'])->orderBy('follow_up_date');if($r->filled('status'))$q->where('status',$r->status);return $q->paginate($r->integer('per_page',30));}
 public function createFollowup(Request $r){$data=$r->validate(['client_id'=>'required|exists:clients,id','invoice_id'=>'nullable|exists:invoices,id','follow_up_date'=>'required|date','channel'=>'required|in:phone,email,sms,whatsapp,visit,other','notes'=>'nullable|string']);$company=$r->user()->company_id;abort_unless(\App\Models\Client::where('company_id',$company)->whereKey($data['client_id'])->exists(),422,'Invalid client.');if(!empty($data['invoice_id']))abort_unless(Invoice::where('company_id',$company)->where('client_id',$data['client_id'])->whereKey($data['invoice_id'])->exists(),422,'Invoice does not belong to the selected client.');$data+=['company_id'=>$company,'user_id'=>$r->user()->id,'status'=>'planned'];return response()->json(CollectionFollowup::create($data)->load(['client','invoice']),201);}
 public function completeFollowup(Request $r,CollectionFollowup $followup){abort_unless($followup->company_id===$r->user()->company_id,404);$followup->update(['status'=>'completed','completed_at'=>now()]);return $followup->fresh()->load(['client','invoice']);}
 public function insights(Request $r){$report=app(ReportController::class)->overview($r);return $report;}
 public function export(Request $r,string $type){$company=$r->user()->company_id;$headers=['Content-Type'=>'text/csv; charset=UTF-8','Content-Disposition'=>'attachment; filename="mauzohub-'.$type.'-'.now()->format('Ymd-His').'.csv"'];return response()->stream(function()use($type,$company){$out=fopen('php://output','w');if($type==='sales'){$rows=\App\Models\Sale::where('company_id',$company)->with('client')->latest('sale_date')->get();fputcsv($out,['Sale','Date','Client','Status','Payment Status','Total']);foreach($rows as $x)fputcsv($out,[$x->sale_number,$x->sale_date,$x->client?->name,$x->status,$x->payment_status,$x->total]);}elseif($type==='invoices'){$rows=Invoice::where('company_id',$company)->with('client')->latest('issue_date')->get();fputcsv($out,['Invoice','Issue Date','Due Date','Client','Status','Total','Paid','Balance']);foreach($rows as $x)fputcsv($out,[$x->invoice_number,$x->issue_date,$x->due_date,$x->client?->name,$x->status,$x->total,$x->amount_paid,$x->balance]);}elseif($type==='payments'){$rows=\App\Models\Payment::where('company_id',$company)->with('client')->latest('payment_date')->get();fputcsv($out,['Payment','Date','Client','Method','Reference','Amount']);foreach($rows as $x)fputcsv($out,[$x->payment_number,$x->payment_date,$x->client?->name,$x->method,$x->reference,$x->amount]);}elseif($type==='expenses'){$rows=\App\Models\Expense::where('company_id',$company)->with('category')->latest('expense_date')->get();fputcsv($out,['Expense','Date','Category','Description','Method','Amount']);foreach($rows as $x)fputcsv($out,[$x->expense_number,$x->expense_date,$x->category?->name,$x->description,$x->payment_method,$x->amount]);}else{fputcsv($out,['Unsupported export']);}fclose($out);},200,$headers);}
}
